(753, '20251117-001-79e1e', '2025-11-17', 'JEANETTE P. CABAB', 2082, 'LPDD-WRUS', 'REGIONAL OFFICE', 'Forest Ranger', '09301597903', 'jeanettepcabab@gmail.com', 'Technical Assistance', '', 'The monitor was not able to open or not serviceable. ', '103', 'Completed', 101, 'During inspection, the monitor displayed no signal, and the HDMI cable was identified as faulty.\r\nAction Taken:  Replace HDMI cable only.\r\nRecommendation: Use a properly functioning HDMI cable to prevent signal loss.', 'RO LPDD', '', 34005, 0, '', 4, '2025-11-17 02:10:05'),
(754, '20251117-001-8b3ac', '2025-11-17', 'GEROME G. SALVADOR', 1894, 'CDD/PABES', 'REGIONAL OFFICE', 'FT II', '09518812063', 'pawczmscaraga@yahoo.com', 'Zoom', '', 'Meeting Title: Regional Cave Comittee Meeting for the 4th quarter. in Water Gate pavilion\r\nDate & Time: 11/26/2025\r\nBlended or Online: Blended ', '102', 'Completed', 101, 'Meeting ID & Passcode Provided', 'RO CDD', '', 0, 1, '', 4, '2025-11-17 06:27:46'),
